-- OAuth のリフレッシュトークン（docs/mcp.md）。平文は保存せず、SHA-256 のハッシュだけを持つ。使うたびに作り直す（1 回しか使えない）
CREATE TABLE IF NOT EXISTS _aegis_oauth_refresh_tokens (id VARCHAR(255) PRIMARY KEY, token_hash VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(255) NOT NULL, client_hash VARCHAR(255) NOT NULL, client_name VARCHAR(255) NOT NULL, scope VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL, access_token_id VARCHAR(255) NOT NULL, created_at VARCHAR(255) NOT NULL, expires_at VARCHAR(255) NOT NULL, INDEX idx_aegis_oauth_refresh_user (username));
